    /**
     * Handles loading a Activity using a UUID
     * @param		UUID uuid 
     * @return		Activity
     */    
    @GetMapping("/load")
    public Activity load( @RequestParam(required=true) UUID uuid ) {    	
    	Activity entity = null;

    	try {  
    		entity = service.getActivity( new ActivityFetchOneSummary( uuid ) );   
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Activity using Id " + uuid );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Activity business objects
     * @return		Set<Activity>
     */
    @GetMapping("/")
    public List<Activity> loadAll() {                
    	List<Activity> activityList = null;
        
    	try {
            // load the Activity
            activityList = service.getAllActivity();
            
            if ( activityList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Activitys" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Activitys ", exc );
        	return null;
        }

        return activityList;
                            
    }

